import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { promises as fs } from "node:fs";
import path from "node:path";
import { CompleteMultiPartUploadUseCase } from "~/features/CompleteMultiPartUpload/CompleteMultiPartUploadUseCase.js";
import { writeMultipartUploadInfo } from "~/utils/multipartUploadInfo.js";
import {
    cleanupStorage,
    makeConfig,
    makeTenantContext,
    setupStorage,
    TENANT_ID
} from "./utils/helpers.js";

// Upload ids are generated by `CreateMultiPartUpload` (an `mdbid`).
const UPLOAD_ID = "65f1a2b3c4d5e6f708192a3b";
const OTHER_UPLOAD_ID = "65f1a2b3c4d5e6f708192a3c";

let storagePath: string;

const multipartDirOf = (uploadId: string) => {
    return path.join(storagePath, "tenants", TENANT_ID, "multipart", uploadId);
};

const createUpload = async (uploadId: string, fileKey: string, parts: string[]) => {
    const multipartDir = multipartDirOf(uploadId);
    await fs.mkdir(multipartDir, { recursive: true });
    await writeMultipartUploadInfo(multipartDir, { fileKey });
    for (const [index, part] of parts.entries()) {
        await fs.writeFile(path.join(multipartDir, `part-${index + 1}`), Buffer.from(part));
    }
};

beforeEach(async () => {
    storagePath = await setupStorage();
});

afterEach(async () => {
    await cleanupStorage();
});

describe("complete multipart upload", () => {
    it("should assemble parts into a final file", async () => {
        const tenantContext = makeTenantContext();
        const fileKey = "abc/myfile.bin";
        await createUpload(UPLOAD_ID, fileKey, ["AAA", "BBB", "CCC"]);

        const useCase = new CompleteMultiPartUploadUseCase(tenantContext, makeConfig());
        await useCase.execute({ fileKey, uploadId: UPLOAD_ID });

        const finalPath = path.join(storagePath, "tenants", TENANT_ID, "files", fileKey);
        const finalData = await fs.readFile(finalPath);
        expect(finalData.toString()).toBe("AAABBBCCC");

        const dirExists = await fs.stat(multipartDirOf(UPLOAD_ID)).catch(() => null);
        expect(dirExists).toBeNull();
    });

    it("should reject an upload id that was not generated by the server", async () => {
        const tenantContext = makeTenantContext();
        const useCase = new CompleteMultiPartUploadUseCase(tenantContext, makeConfig());

        await expect(
            useCase.execute({ fileKey: "file.txt", uploadId: "../escape" })
        ).rejects.toThrow("Invalid upload id.");
    });

    it("should only complete an upload into the file it was created for", async () => {
        const tenantContext = makeTenantContext();
        await createUpload(UPLOAD_ID, "abc/a.txt", ["hello"]);
        await createUpload(OTHER_UPLOAD_ID, "def/b.txt", ["world"]);

        const useCase = new CompleteMultiPartUploadUseCase(tenantContext, makeConfig());

        await expect(
            useCase.execute({ fileKey: "def/b.txt", uploadId: UPLOAD_ID })
        ).rejects.toThrow("Upload not found.");
        await expect(
            useCase.execute({ fileKey: "../../etc/passwd", uploadId: UPLOAD_ID })
        ).rejects.toThrow("Upload not found.");

        // Neither upload was touched.
        expect(await fs.stat(multipartDirOf(UPLOAD_ID)).catch(() => null)).not.toBeNull();
        expect(await fs.stat(multipartDirOf(OTHER_UPLOAD_ID)).catch(() => null)).not.toBeNull();
    });
});
